def git(*args, text=True):
    return subprocess.run(['git', '-C', REPO] + list(args), capture_output=True, text=text, check=True).stdout

COORD = {
    'explorations/coordinator/FACTS.md', 'explorations/coordinator/POSITIONS.md',
    'explorations/coordinator/PLAN.md', 'explorations/coordinator/INDEX.md',
    'explorations/fortress-gap-ledger.md', 'explorations/microgpt-run-c-handover.md',
}
TEST_DIRS = ('ProjectFortress/tests/', 'ProjectFortress/compiler_tests/', 'ProjectFortress/library_tests/',
             'ProjectFortress/compiler_regressions/', 'ProjectFortress/linker_tests/', 'ProjectFortress/not_passing_yet/',
             'ProjectFortress/not_working_', 'ProjectFortress/other_compiler_tests/', 'ProjectFortress/parser_tests/',
             'ProjectFortress/shelltests/', 'ProjectFortress/syntax_abstraction_tests/', 'ProjectFortress/test/',
             'ProjectFortress/test_library/', 'ProjectFortress/long_term_not_working/', 'ProjectFortress/static_tests/')
CAPT = {'.txt', '.tsv', '.out', '.log', '.csv', '.json'}
PROBE = {'.fss', '.fsi', '.test'}
SCRIPT = {'.sh', '.py', '.js', '.java', '.scala', '.awk', '.pl', '.sed', '.bash', '.mjs', '.jq'}

def cat(path):
    if path in COORD:
        return 'COORD'
    if path.startswith('Library/') or path.startswith('ProjectFortress/LibraryBuiltin/'):
        return 'CODE.library'
    if path.startswith('ProjectFortress/src/'):
        if path.endswith('.java'): return 'CODE.java'
        if path.endswith('.scala'): return 'CODE.scala'
        return 'CODE.src-other'
    if path.startswith('ProjectFortress/astgen/'):
        return 'CODE.astgen'
    if os.path.basename(path) in ('build.xml', 'build.properties') or path.startswith('bin/'):
        return 'CODE.build'
    if path.startswith('Specification/'):
        if path == 'Specification/fortress.pdf': return 'SPEC.pdf'
        if path.endswith('.tex'): return 'SPEC.tex'
        return 'SPEC.other'
    if path.startswith(TEST_DIRS):
        return 'TESTS'
    if path.startswith('explorations/'):
        ext = os.path.splitext(path)[1].lower()
        if ext == '.md': return 'REC.REPORTS'
        if ext in CAPT: return 'REC.CAPTURES'
        if ext in PROBE: return 'REC.PROBES'
        if ext in SCRIPT: return 'REC.SCRIPTS'
        return 'REC.OTHER'
    return 'OUTSIDE'

def parse_commit(c):
    """Return list of (status, old, new, add, dele) for commit c, rename-aware."""
    raw = git('show', '-M', '-z', '--format=', '--raw', '--numstat', c)
    toks = raw.split('\0')
    # raw part: ':mode mode sha sha status\0path\0[path2\0]' ; numstat part: 'a\td\tpath\0' or 'a\td\t\0old\0new\0'
    entries = []
    nums = []
    i = 0
    while i < len(toks):
        t = toks[i]
        if t.startswith(':') or t.startswith('\n:'):
            t = t.lstrip('\n')
            st = t.split()[-1]
            if st[0] in 'RC':
                entries.append((st[0], toks[i+1], toks[i+2])); i += 3
            else:
                entries.append((st[0], toks[i+1], toks[i+1])); i += 2
        elif t.strip() == '':
            i += 1
        else:
            t = t.lstrip('\n')
            parts = t.split('\t')
            a, d = parts[0], parts[1]
            if parts[2] == '':
                old, new = toks[i+1], toks[i+2]; i += 3
            else:
                old = new = parts[2]; i += 1
            nums.append((a, d, old, new))
    assert len(entries) == len(nums), (c, len(entries), len(nums))
    out = []
    for (st, o, n), (a, d, o2, n2) in zip(entries, nums):
        assert n == n2, (c, n, n2)
        out.append((st, o, n, None if a == '-' else int(a), None if d == '-' else int(d)))
    return out

def blob_size(rev, path):
    try:
        return int(git('cat-file', '-s', f'{rev}:{path}').strip())
    except subprocess.CalledProcessError:
        return None

def blob_lines(rev, path):
    try:
        data = subprocess.run(['git', '-C', REPO, 'show', f'{rev}:{path}'], capture_output=True, check=True).stdout
        return data.count(b'\n')
    except subprocess.CalledProcessError:
        return None

def main():
    name = sys.argv[1]
    landing = sys.argv[2]
    commits = sys.argv[3:]
    rows = []
    for c in commits:
        for st, o, n, a, d in parse_commit(c):
            rows.append(dict(commit=c, st=st, old=o, new=n, add=a, dele=d, cat=cat(n), oldcat=cat(o)))
    with open(os.path.join(OUT, f'{name}-rows.json'), 'w') as f:
        json.dump(rows, f)
    print(len(rows), 'numstat rows')

if __name__ == '__main__':
    main()

